  if ([IO.Path]::IsPathRooted($Relative) -or $Relative.Contains('\') -or $Relative -match '(^|/)\.{1,2}(/|$)' -or $Relative -match '(^/|//$|/$)') { throw 'Invalid archive relative path.' }
